import * as fs from "fs";

const input: string[] = fs.readFileSync(0, "utf8").trim().split("\n");

let n = BigInt(input[0]);
if (n === 0n) {
  console.log("0");
} else {
  // 2 で割った余りを下の桁から集める
  const bits: string[] = [];
  while (n > 0n) {
    bits.push((n % 2n).toString());
    n /= 2n;
  }
  console.log(bits.reverse().join(""));
}
